function chatMemoryLimits(env={}){const bounded=(value,fallback,min,max)=>{const n=Number(value);return Number.isInteger(n)&&n>=min&&n<=max?n:fallback};return {messages:bounded(env.CHAT_CONTEXT_MESSAGES,80,12,200),characters:bounded(env.CHAT_CONTEXT_CHARACTERS,48000,8000,120000)}}
function boundChatHistory(messages,characters){const selected=[];let remaining=characters;for(let i=messages.length-1;i>=0&&remaining>0;i--){const m=messages[i],content=String(m.content||'');const text=content.length<=remaining?content:content.slice(0,remaining);if(text)selected.unshift({...m,content:text});remaining-=text.length;}return selected;}
function aiProvider(env){return env.AI_PROVIDER||'openai'}
