export default {async fetch(request,env){const url=new URL(request.url);const adminPath=url.pathname==='/admin'||url.pathname.startsWith('/admin/')||url.pathname.startsWith('/api/admin/');if(adminPath&&!isAdmin(request,env))return url.pathname.startsWith('/api/')?json({error:'Only the site owner can access agent settings.'},403):new Response('Owner access required. Sign in to this Site with the owner account.',{status:403,headers:{'Content-Type':'text/plain; charset=utf-8'}});const idleRoute=await reactionIdleRoute(request,env,url);if(idleRoute)return idleRoute;const reactionsRoute=await reactionRoutes(request,env,url);if(reactionsRoute)return reactionsRoute;const experienceRoute=await chatExperienceRoutes(request,env,url);if(experienceRoute)return experienceRoute;const storedRoute=await chatStorageRoutes(request,env,url);if(storedRoute)return storedRoute;if(url.pathname==='/admin/sessions')return new Response(sessionsPage,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});if(url.pathname==='/admin'||url.pathname==='/admin/')return new Response(adminPage,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});if(url.pathname==='/api/admin/settings'){if(request.method==='GET'){try{return json({...await readSettings(env),defaults})}catch{return json({error:'Settings storage is unavailable. Please try again.'},503)}}if(request.method!=='PUT')return json({error:'Method not allowed.'},405);if(request.headers.get('Origin')!==url.origin)return json({error:'Invalid origin.'},403);let data;try{data=await readJson(request,2000000)}catch{return json({error:'Invalid settings request.'},400)}if(data.reactions!==undefined&&!validReactions(data.reactions))return json({error:'Check reaction rules: at most 30 unique rules, a name, valid trigger, text or image, keywords or custom condition where needed, language, and integer levels from 0 to 10.'},400);if(!validSettings(data))return json({error:'Persona and tone are required and each limited to 5,000 words, both scales must be integers from 0 to 10, and all five empathy stages need a heading, trigger context, behaviour, humour allowance and combined example. Happy path needs four stage headings, contexts and guidance, with optional examples; shared rules and stage guidance are limited to 6,000 characters each. The optional conversation goal is limited to 3,000 characters. Their integer score ranges must cover 0–10 in order with no gaps or overlaps.'},400);if(data.reactions===undefined){data.reactions=(await readSettings(env)).settings.reactions;}if(data.personalityScale===undefined||data.scope===undefined){const old=(await readSettings(env)).settings;data.personalityScale??=old.personalityScale;data.scope??=old.scope;}if(data.happyPath===undefined){try{data.happyPath=(await readSettings(env)).settings.happyPath}catch{return json({error:'Unable to preserve the saved happy path. Please reload before saving.'},503)}}const saved={settings:settingsOnly(data),updatedAt:new Date().toISOString()};try{if(!env.BUCKET)throw Error('No storage');await env.BUCKET.put('agent/settings.json',JSON.stringify(saved),{httpMetadata:{contentType:'application/json'}});return json(saved)}catch{return json({error:'Settings could not be saved. Your changes have not been applied.'},503)}}if(url.pathname==='/api/admin/preview'){if(request.method!=='POST')return json({error:'Method not allowed.'},405);if(request.headers.get('Origin')!==url.origin)return json({error:'Invalid origin.'},403);let body;try{body=await readJson(request,2100000)}catch{return json({error:'Invalid preview request.'},400)}if(!validSettings(body.settings)||!validMessages(body.messages)||!validContext(body.context))return json({error:'Invalid preview settings or messages.'},400);return storedChatReply(request,env,body,'preview',settingsOnly(body.settings))}if(Object.hasOwn(scalePortraits,url.pathname))return new Response(Uint8Array.from(atob(scalePortraits[url.pathname]),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/png','Cache-Control':'public, max-age=86400','X-Content-Type-Options':'nosniff'}});if(url.pathname==='/chat-reaction.png')return new Response(Uint8Array.from(atob(scopeReactionImage),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/png','Cache-Control':'public, max-age=86400','X-Content-Type-Options':'nosniff'}});if(url.pathname==='/privacy')return new Response(privacyPage,{headers:{'Content-Type':'text/html; charset=utf-8','X-Content-Type-Options':'nosniff'}});if(url.pathname==='/home-tour-poster.png'){return new Response(Uint8Array.from(atob(photo),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/png','Cache-Control':'public, max-age=86400'}})}if(url.pathname==='/api/shows'){if(request.method!=='GET')return json({error:'Method not allowed.'},405);return json({shows:showData,sample:true})}if(url.pathname==='/shows')return new Response(showsPage,{headers:{'Content-Type':'text/html; charset=utf-8','X-Content-Type-Options':'nosniff'}});if(url.pathname==='/api/status')return json({ready:!!aiConnected(env)&&!!env.DB,storageReady:!!env.DB});if(url.pathname==='/api/chat'){if(request.method!=='POST')return json({error:'Use POST.'},405);if(request.headers.get('Origin')!==url.origin)return json({error:'Invalid origin.'},403);let body;try{body=await readJson(request)}catch{return json({error:'Invalid message.'},400)}if(!validMessages(body.messages)||!validContext(body.context))return json({error:'Invalid messages.'},400);return storedChatReply(request,env,body,'live')}if(url.pathname!=='/')return new Response('Not found',{status:404});const home=page;return new Response(home,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}})}};
